CREATE TABLE tenant (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(160) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE company (id BIGINT PRIMARY KEY AUTO_INCREMENT, tenant_id BIGINT NOT NULL, name VARCHAR(160) NOT NULL, code VARCHAR(40) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE KEY uq_company_code(tenant_id,code));
CREATE TABLE user_account (id BIGINT PRIMARY KEY AUTO_INCREMENT, tenant_id BIGINT NOT NULL, email VARCHAR(190) NOT NULL, password_hash VARCHAR(100) NOT NULL, full_name VARCHAR(160) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE KEY uq_user_email(tenant_id,email));
CREATE TABLE user_company_assignment (user_id BIGINT NOT NULL, company_id BIGINT NOT NULL, role_name VARCHAR(40) NOT NULL, PRIMARY KEY(user_id,company_id));
CREATE TABLE customer (id BIGINT PRIMARY KEY AUTO_INCREMENT, tenant_id BIGINT NOT NULL, company_id BIGINT NOT NULL, code VARCHAR(40) NOT NULL, name VARCHAR(160) NOT NULL, email VARCHAR(190), active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE KEY uq_customer(tenant_id,company_id,code));
CREATE TABLE supplier (id BIGINT PRIMARY KEY AUTO_INCREMENT, tenant_id BIGINT NOT NULL, company_id BIGINT NOT NULL, code VARCHAR(40) NOT NULL, name VARCHAR(160) NOT NULL, lead_days INT NOT NULL DEFAULT 5, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE KEY uq_supplier(tenant_id,company_id,code));
CREATE TABLE product (id BIGINT PRIMARY KEY AUTO_INCREMENT, tenant_id BIGINT NOT NULL, company_id BIGINT NOT NULL, sku VARCHAR(60) NOT NULL, name VARCHAR(160) NOT NULL, kind VARCHAR(30) NOT NULL, unit VARCHAR(20) NOT NULL, reorder_point DECIMAL(14,3) NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE KEY uq_product(tenant_id,company_id,sku));
CREATE TABLE warehouse (id BIGINT PRIMARY KEY AUTO_INCREMENT, tenant_id BIGINT NOT NULL, company_id BIGINT NOT NULL, code VARCHAR(40) NOT NULL, name VARCHAR(160) NOT NULL, UNIQUE KEY uq_warehouse(tenant_id,company_id,code));
CREATE TABLE bom (id BIGINT PRIMARY KEY AUTO_INCREMENT, tenant_id BIGINT NOT NULL, company_id BIGINT NOT NULL, product_id BIGINT NOT NULL, revision INT NOT NULL, status VARCHAR(24) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_bom(tenant_id,company_id,product_id,revision));
CREATE TABLE bom_line (id BIGINT PRIMARY KEY AUTO_INCREMENT, bom_id BIGINT NOT NULL, component_id BIGINT NOT NULL, quantity DECIMAL(14,3) NOT NULL);
CREATE TABLE customer_order (id BIGINT PRIMARY KEY AUTO_INCREMENT, tenant_id BIGINT NOT NULL, company_id BIGINT NOT NULL, order_no VARCHAR(40) NOT NULL, customer_id BIGINT NOT NULL, status VARCHAR(30) NOT NULL, due_date DATE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_order(tenant_id,company_id,order_no));
CREATE TABLE order_line (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, product_id BIGINT NOT NULL, sku_snapshot VARCHAR(60) NOT NULL, name_snapshot VARCHAR(160) NOT NULL, quantity DECIMAL(14,3) NOT NULL, bom_revision_snapshot INT, unit_snapshot VARCHAR(20) NOT NULL);
CREATE TABLE manufacturing_order (id BIGINT PRIMARY KEY AUTO_INCREMENT, tenant_id BIGINT NOT NULL, company_id BIGINT NOT NULL, work_no VARCHAR(40) NOT NULL, order_line_id BIGINT NOT NULL, product_id BIGINT NOT NULL, quantity DECIMAL(14,3) NOT NULL, produced DECIMAL(14,3) NOT NULL DEFAULT 0, status VARCHAR(30) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_work_no(tenant_id,company_id,work_no));
CREATE TABLE work_material (id BIGINT PRIMARY KEY AUTO_INCREMENT, work_order_id BIGINT NOT NULL, component_id BIGINT NOT NULL, sku_snapshot VARCHAR(60) NOT NULL, name_snapshot VARCHAR(160) NOT NULL, unit_snapshot VARCHAR(20) NOT NULL, quantity_per DECIMAL(14,3) NOT NULL, required_quantity DECIMAL(14,3) NOT NULL);
CREATE TABLE purchase_order (id BIGINT PRIMARY KEY AUTO_INCREMENT, tenant_id BIGINT NOT NULL, company_id BIGINT NOT NULL, po_no VARCHAR(40) NOT NULL, supplier_id BIGINT NOT NULL, status VARCHAR(30) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_po(tenant_id,company_id,po_no));
CREATE TABLE purchase_order_line (id BIGINT PRIMARY KEY AUTO_INCREMENT, po_id BIGINT NOT NULL, product_id BIGINT NOT NULL, quantity DECIMAL(14,3) NOT NULL, received DECIMAL(14,3) NOT NULL DEFAULT 0);
CREATE TABLE inventory_movement (id BIGINT PRIMARY KEY AUTO_INCREMENT, tenant_id BIGINT NOT NULL, company_id BIGINT NOT NULL, warehouse_id BIGINT NOT NULL, product_id BIGINT NOT NULL, movement_type VARCHAR(32) NOT NULL, quantity DECIMAL(14,3) NOT NULL, reference_type VARCHAR(32) NOT NULL, reference_id BIGINT, idempotency_key VARCHAR(100) NOT NULL, note VARCHAR(255), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_movement_idempotency(tenant_id,company_id,idempotency_key), KEY ix_inventory_scope(tenant_id,company_id,product_id));
CREATE TABLE audit_event (id BIGINT PRIMARY KEY AUTO_INCREMENT, tenant_id BIGINT NOT NULL, company_id BIGINT, actor_id BIGINT, event_type VARCHAR(80) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id BIGINT, detail_json JSON, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
